import React, { useCallback, useEffect, useRef, useState } from "react";
import { Box, Static, Text, render, useApp, useInput, useStdin } from "ink";
import { COMMANDS, resolveCommand, runCommand } from "./commands.ts";
import { type AgentState, newAgentState, runTurn } from "./core/agent.ts";
import { AUTO_COMPACT_THRESHOLD, compactHistory } from "./core/compact.ts";
import { EFFORT_LEVELS, MODEL, VERSION, type Effort, loadConfig, saveConfig } from "./core/config.ts";
import { SESSION_ID, trace } from "./core/diagnostics.ts";
import { logger } from "./core/logger.ts";
import { formatCost } from "./core/pricing.ts";
import { visiblePrefix } from "./core/protocol.ts";
import { loadSession, saveSession } from "./core/session.ts";
import { expandSkill, listSkills, loadSkill } from "./core/skills.ts";
import type { ApprovalRequest, TodoItem } from "./core/tools.ts";
import { Approval } from "./components/Approval.tsx";
import { Input } from "./components/Input.tsx";
import { Intro } from "./components/Intro.tsx";
import { Markdown } from "./components/Markdown.tsx";
import { SPINNER_FRAMES, THINKING_VERBS, theme } from "./theme.ts";

type ItemKind = "banner" | "user" | "assistant" | "tool" | "notice" | "error" | "shell";

interface Item {
  id: number;
  kind: ItemKind;
  text: string;
  tool?: string;
  status?: "ok" | "error";
  hint?: string;
}

let nextId = 1;

interface PendingApproval {
  request: ApprovalRequest;
  resolve: (ok: boolean) => void;
}

interface Suggestion {
  name: string;
  description: string;
}

function toolHint(args: Record<string, unknown>): string {
  for (const key of ["command", "path", "pattern", "query", "task", "name", "fact", "ids"]) {
    const v = args[key];
    if (typeof v === "string" && v) return v.length > 64 ? v.slice(0, 64) + "…" : v;
  }
  return "";
}

function fmtTok(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1000) return `${(n / 1000).toFixed(1)}k`;
  return String(Math.round(n));
}

const EFFORT_OPTIONS: Array<{ value: Effort; blurb: string }> = [
  { value: "low", blurb: "quick answers · 6 tool rounds" },
  { value: "medium", blurb: "balanced · 14 tool rounds" },
  { value: "high", blurb: "thorough · 28 tool rounds" },
  { value: "max", blurb: "exhaustive · 50 tool rounds" },
  { value: "ultracode", blurb: "plans · todos · parallel agents · unlimited rounds" },
];

/** Tokens-per-second meter over a sliding window, with a 10s-vs-previous-10s trend. */
class TpsMeter {
  private stamps: number[] = [];
  record(): void {
    this.stamps.push(Date.now());
    if (this.stamps.length > 20000) this.stamps.splice(0, 10000);
  }
  reset(): void {
    this.stamps = [];
  }
  tps(): number {
    const now = Date.now();
    const recent = this.stamps.filter((s) => now - s <= 2000);
    return recent.length / 2;
  }
  trend(): "up" | "down" {
    const now = Date.now();
    const last10 = this.stamps.filter((s) => now - s <= 10_000).length;
    const prev10 = this.stamps.filter((s) => now - s > 10_000 && now - s <= 20_000).length;
    return last10 >= prev10 ? "up" : "down";
  }
}

export function App({ opts }: { opts: { yolo: boolean; intro: boolean; resume?: string } }) {
  const { exit } = useApp();
  const { stdin } = useStdin();
  const config = loadConfig();
  if (opts.yolo) config.yolo = true;

  const [phase, setPhase] = useState<"intro" | "ready">(
    opts.intro && config.intro ? "intro" : "ready",
  );
  const [items, setItems] = useState<Item[]>([]);
  const [running, setRunning] = useState(false);
  const [stream, setStream] = useState("");
  const [thoughtLines, setThoughtLines] = useState<string[]>([]);
  const [thoughtExpanded, setThoughtExpanded] = useState(false);
  const [thinking, setThinking] = useState(false);
  const [activeTool, setActiveTool] = useState<{ tool: string; hint: string } | null>(null);
  const [approval, setApproval] = useState<PendingApproval | null>(null);
  const [todos, setTodos] = useState<TodoItem[]>([]);
  const [spin, setSpin] = useState(0);
  const [elapsed, setElapsed] = useState(0);
  const [tps, setTps] = useState(0);
  const [tpsTrend, setTpsTrend] = useState<"up" | "down">("up");
  const [usage, setUsage] = useState({ prompt: 0, completion: 0, total: 0 });
  const [cost, setCost] = useState(0);
  const [ctxTokens, setCtxTokens] = useState(0);
  const [history, setHistory] = useState<string[]>([]);
  const [inputValue, setInputValue] = useState("");
  const [suggestions, setSuggestions] = useState<Suggestion[]>([]);
  const [suggestionIdx, setSuggestionIdx] = useState(0);
  const [effortMenu, setEffortMenu] = useState(false);
  const [effortMenuIdx, setEffortMenuIdx] = useState(0);
  const [ctrlCArmed, setCtrlCArmed] = useState(false);

  const stateRef = useRef<AgentState>(newAgentState());
  const abortRef = useRef<AbortController | null>(null);
  const verbRef = useRef(THINKING_VERBS[Math.floor(Math.random() * THINKING_VERBS.length)]);
  const titleRef = useRef("");
  const meterRef = useRef(new TpsMeter());
  const reasoningBufRef = useRef("");
  const activeToolHintRef = useRef("");

  const push = useCallback((item: Omit<Item, "id">) => {
    setItems((prev) => [...prev, { ...item, id: nextId++ }]);
  }, []);

  useEffect(() => {
    if (phase !== "ready") return;
    push({ kind: "banner", text: "" });
    trace("session.start", { mode: "tui" });
    if (opts.resume) {
      const loaded = loadSession(opts.resume);
      if (loaded) {
        stateRef.current.messages = loaded.messages;
        titleRef.current = loaded.title;
        push({
          kind: "notice",
          text: `resumed session ${opts.resume} — "${loaded.title}" (${loaded.messages.length} messages)`,
        });
      } else {
        push({ kind: "error", text: `could not load session ${opts.resume}` });
      }
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [phase]);

  useEffect(() => {
    if (!running) return;
    const started = Date.now();
    const t = setInterval(() => {
      setSpin((s) => s + 1);
      setElapsed(Math.floor((Date.now() - started) / 1000));
      setTps(meterRef.current.tps());
      setTpsTrend(meterRef.current.trend());
    }, 120);
    return () => clearInterval(t);
  }, [running]);

  // Mouse click toggles the thought dropdown while thinking is shown.
  useEffect(() => {
    const wantMouse = running && loadConfig().thoughts;
    if (!wantMouse || !stdin) return;
    process.stdout.write("\x1b[?1000h\x1b[?1006h");
    const onData = (data: Buffer) => {
      const s = data.toString("latin1");
      if (/\x1b\[<0;\d+;\d+M/.test(s)) setThoughtExpanded((e) => !e);
    };
    stdin.on("data", onData);
    return () => {
      stdin.off("data", onData);
      process.stdout.write("\x1b[?1006l\x1b[?1000l");
    };
  }, [running, stdin]);

  useInput(
    (input, key) => {
      if (effortMenu) {
        if (key.upArrow) setEffortMenuIdx((i) => (i + EFFORT_OPTIONS.length - 1) % EFFORT_OPTIONS.length);
        else if (key.downArrow) setEffortMenuIdx((i) => (i + 1) % EFFORT_OPTIONS.length);
        else if (key.return) {
          const chosen = EFFORT_OPTIONS[effortMenuIdx].value;
          saveConfig({ effort: chosen });
          setEffortMenu(false);
          push({ kind: "notice", text: `effort set to ${chosen} — ${EFFORT_OPTIONS[effortMenuIdx].blurb}` });
        } else if (key.escape) setEffortMenu(false);
        return;
      }
      if (key.ctrl && input === "t") {
        setThoughtExpanded((e) => !e);
        return;
      }
      if (key.escape && running) {
        abortRef.current?.abort();
        return;
      }
      if (key.ctrl && input === "c") {
        if (ctrlCArmed) {
          saveSession(stateRef.current, titleRef.current || "untitled");
          trace("session.end", { mode: "tui", usage: stateRef.current.totalUsage });
          exit();
          return;
        }
        setCtrlCArmed(true);
        setTimeout(() => setCtrlCArmed(false), 1500);
      }
    },
    { isActive: phase === "ready" },
  );

  const appendThought = useCallback((delta: string) => {
    reasoningBufRef.current += delta;
    let buf = reasoningBufRef.current;
    if (/<\/think>/i.test(buf)) setThinking(false);
    else if (/<think>/i.test(buf)) setThinking(true);
    const cleaned = buf.replace(/<\/?think>/gi, "");
    const lines = cleaned.split("\n").map((l) => l.trim()).filter(Boolean);
    setThoughtLines(lines.slice(-200));
  }, []);

  const run = useCallback(
    async (text: string) => {
      setRunning(true);
      setStream("");
      setThoughtLines([]);
      setThinking(false);
      setTodos([]);
      meterRef.current.reset();
      reasoningBufRef.current = "";
      verbRef.current = THINKING_VERBS[Math.floor(Math.random() * THINKING_VERBS.length)];
      const abort = new AbortController();
      abortRef.current = abort;
      let streamed = "";
      try {
        await runTurn(
          stateRef.current,
          text,
          loadConfig().effort,
          {
            onDelta: (d, channel) => {
              meterRef.current.record();
              if (channel === "content") {
                streamed += d;
                setStream(visiblePrefix(streamed));
              } else {
                appendThought(d);
              }
            },
            onAssistantText: (t) => {
              push({ kind: "assistant", text: t });
              streamed = "";
              setStream("");
            },
            onToolStart: (tool, args) => {
              streamed = "";
              setStream("");
              reasoningBufRef.current = "";
              setThoughtLines([]);
              const hint = toolHint(args);
              activeToolHintRef.current = hint;
              setActiveTool({ tool, hint });
            },
            onToolEnd: (tool, status, output) => {
              setActiveTool(null);
              const preview =
                tool === "bash" || tool === "grep" || tool === "web_search" || tool === "subagent" || tool === "await_agents"
                  ? output.split("\n").slice(0, 3).join("\n").slice(0, 240)
                  : output.split("\n")[0]?.slice(0, 120) ?? "";
              push({ kind: "tool", text: preview, tool, status, hint: activeToolHintRef.current });
            },
            onApproval: (request) =>
              new Promise<boolean>((resolve) => setApproval({ request, resolve })),
            onUsage: (u, c) => {
              setUsage((prev) => ({
                prompt: prev.prompt + u.prompt_tokens,
                completion: prev.completion + u.completion_tokens,
                total: prev.total + u.total_tokens,
              }));
              setCost((prev) => prev + c);
              setCtxTokens(u.prompt_tokens);
            },
            onNotice: (t) => push({ kind: "notice", text: t }),
            onTodos: (t) => setTodos(t),
          },
          abort.signal,
        );
      } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        if (msg === "aborted" || abort.signal.aborted) {
          push({ kind: "notice", text: "interrupted — context kept, carry on when ready" });
        } else {
          push({ kind: "error", text: msg });
          logger.error("tui.turn_error", msg);
        }
      } finally {
        setRunning(false);
        setActiveTool(null);
        setApproval(null);
        setStream("");
        setThinking(false);
        if (!titleRef.current) titleRef.current = text.slice(0, 60);
        saveSession(stateRef.current, titleRef.current);
        if (stateRef.current.lastPromptTokens > AUTO_COMPACT_THRESHOLD) {
          push({ kind: "notice", text: "context is getting heavy — auto-compacting…" });
          try {
            const result = await compactHistory(stateRef.current);
            push({ kind: "notice", text: result });
          } catch {
            push({ kind: "notice", text: "auto-compact failed; /compact to retry" });
          }
        }
      }
    },
    [push, appendThought],
  );

  const computeSuggestions = useCallback((value: string): Suggestion[] => {
    if (!value.startsWith("/") || value.includes(" ")) return [];
    const prefix = value.slice(1).toLowerCase();
    const cmds = COMMANDS.filter((c) => c.name.startsWith(prefix)).map((c) => ({
      name: c.name,
      description: c.description,
    }));
    const skills = listSkills()
      .filter((s) => s.name.startsWith(prefix))
      .map((s) => ({ name: s.name, description: `skill — ${s.description}` }));
    return [...cmds, ...skills].slice(0, 8);
  }, []);

  const onInputChange = useCallback(
    (value: string) => {
      setInputValue(value);
      const next = computeSuggestions(value);
      setSuggestions(next);
      setSuggestionIdx((i) => Math.min(i, Math.max(0, next.length - 1)));
    },
    [computeSuggestions],
  );

  const submit = useCallback(
    (text: string) => {
      setHistory((h) => [...h.filter((x) => x !== text), text].slice(-100));
      setInputValue("");
      setSuggestions([]);

      if (text.startsWith("!")) {
        const cmd = text.slice(1).trim();
        push({ kind: "user", text });
        const proc = Bun.spawnSync(["bash", "-c", cmd], { cwd: process.cwd() });
        const out = (proc.stdout.toString() + proc.stderr.toString()).trim() || "(no output)";
        push({ kind: "shell", text: out.slice(0, 4000), hint: cmd, status: proc.exitCode === 0 ? "ok" : "error" });
        stateRef.current.messages.push({
          role: "user",
          content: `[I ran a shell command myself]\n$ ${cmd}\n${out.slice(0, 2000)}`,
        });
        trace("shell.passthrough", { cmd, exit: proc.exitCode });
        return;
      }

      if (text.startsWith("/")) {
        const rawName = text.slice(1).split(/\s+/)[0];
        const resolved = resolveCommand(rawName);
        const skill = resolved ? null : loadSkill(rawName);
        if (skill) {
          const args = text.slice(1 + rawName.length).trim();
          push({ kind: "user", text });
          push({ kind: "notice", text: `skill /${skill.name}` });
          void run(expandSkill(skill, args));
          return;
        }
        push({ kind: "user", text });
        if (!resolved) {
          const near = COMMANDS.filter((c) => c.name.startsWith(rawName)).map((c) => `/${c.name}`);
          push({
            kind: "assistant",
            text:
              near.length > 0
                ? `ambiguous: did you mean ${near.join(" or ")}?`
                : `unknown command: /${rawName} — try /help`,
          });
          return;
        }
        const canonical = `/${resolved}${text.slice(1 + rawName.length)}`;
        const result = runCommand(canonical, { usage, ctxTokens, cost });
        switch (result.kind) {
          case "text":
            push({ kind: "assistant", text: result.text! });
            return;
          case "effort-menu":
            setEffortMenuIdx(EFFORT_OPTIONS.findIndex((o) => o.value === loadConfig().effort));
            setEffortMenu(true);
            return;
          case "clear":
            stateRef.current = newAgentState();
            titleRef.current = "";
            setUsage({ prompt: 0, completion: 0, total: 0 });
            setCost(0);
            setCtxTokens(0);
            setTodos([]);
            setItems([]);
            push({ kind: "banner", text: "" });
            return;
          case "quit":
            saveSession(stateRef.current, titleRef.current || "untitled");
            trace("session.end", { mode: "tui", usage: stateRef.current.totalUsage });
            exit();
            return;
          case "intro":
            setPhase("intro");
            return;
          case "compact":
            setRunning(true);
            void compactHistory(stateRef.current)
              .then((msg) => push({ kind: "notice", text: msg }))
              .catch((e) => push({ kind: "error", text: String(e) }))
              .finally(() => setRunning(false));
            return;
          case "resume": {
            const loaded = loadSession(result.resumeId!);
            if (loaded) {
              stateRef.current = newAgentState();
              stateRef.current.messages = loaded.messages;
              titleRef.current = loaded.title;
              push({ kind: "notice", text: `resumed "${loaded.title}" (${loaded.messages.length} messages)` });
            } else {
              push({ kind: "error", text: `no session ${result.resumeId} — see /sessions` });
            }
            return;
          }
          case "submit":
            void run(result.text!);
            return;
        }
      }

      push({ kind: "user", text });
      void run(text);
    },
    [push, run, usage, ctxTokens, cost, exit],
  );

  if (phase === "intro") {
    return <Intro onDone={() => setPhase("ready")} />;
  }

  const cfg = loadConfig();
  const thoughtsOn = cfg.thoughts;
  const lastThought = thoughtLines.length > 0 ? thoughtLines[thoughtLines.length - 1] : "";
  const tpsLabel = `${tpsTrend === "up" ? "↑" : "↓"} ${fmtTok(tps)} tps`;

  return (
    <Box flexDirection="column">
      <Static items={items}>
        {(item) => (
          <Box key={item.id} flexDirection="column" marginBottom={item.kind === "tool" ? 0 : 1}>
            {item.kind === "banner" && <Banner />}
            {item.kind === "user" && (
              <Text>
                <Text color={theme.orange} bold>
                  ❯{" "}
                </Text>
                <Text color={theme.dim}>{item.text}</Text>
              </Text>
            )}
            {item.kind === "assistant" && (
              <Box flexDirection="row">
                <Box width={2} flexShrink={0}>
                  <Text color={theme.orange}>✦</Text>
                </Box>
                <Box flexDirection="column" flexGrow={1}>
                  <Markdown text={item.text} />
                </Box>
              </Box>
            )}
            {item.kind === "tool" && (
              <Box flexDirection="column">
                <Text>
                  <Text color={item.status === "ok" ? theme.green : theme.red}>
                    {item.status === "ok" ? "  ⏺" : "  ⊘"}
                  </Text>
                  <Text color={theme.ink}> {item.tool}</Text>
                  {item.hint ? <Text color={theme.dim}> {item.hint}</Text> : null}
                </Text>
                {item.text ? (
                  <Box marginLeft={4} flexDirection="column">
                    {item.text.split("\n").map((l, i) => (
                      <Text key={i} color={theme.faint}>
                        {l}
                      </Text>
                    ))}
                  </Box>
                ) : null}
              </Box>
            )}
            {item.kind === "notice" && (
              <Text color={theme.dim} italic>
                ◦ {item.text}
              </Text>
            )}
            {item.kind === "error" && <Text color={theme.red}>✗ {item.text}</Text>}
            {item.kind === "shell" && (
              <Box flexDirection="column" marginLeft={2}>
                {item.text.split("\n").slice(0, 20).map((l, i) => (
                  <Text key={i} color={item.status === "error" ? theme.red : theme.faint}>
                    {l}
                  </Text>
                ))}
              </Box>
            )}
          </Box>
        )}
      </Static>

      {stream ? (
        <Box flexDirection="row">
          <Box width={2} flexShrink={0}>
            <Text color={theme.orange}>✦</Text>
          </Box>
          <Box flexDirection="column" flexGrow={1}>
            <Markdown text={stream} />
          </Box>
        </Box>
      ) : null}

      {running && thoughtsOn && thoughtLines.length > 0 && (
        <Box
          flexDirection="column"
          borderStyle="round"
          borderColor={theme.faint}
          paddingX={1}
          marginTop={stream ? 1 : 0}
        >
          <Text color={theme.dim}>
            {thoughtExpanded ? "▾" : "▸"} thinking{" "}
            <Text color={theme.faint}>(click or ctrl+t to {thoughtExpanded ? "collapse" : "expand"})</Text>
          </Text>
          {thoughtExpanded ? (
            thoughtLines.map((l, i) => (
              <Text key={i} color={theme.faint} italic>
                {"  "}
                {l}
              </Text>
            ))
          ) : (
            <Text color={theme.faint} italic>
              {"  "}
              {lastThought.slice(-160) || "…"}
            </Text>
          )}
        </Box>
      )}

      {running && (
        <Box>
          <Text color={theme.orange}>{SPINNER_FRAMES[spin % SPINNER_FRAMES.length]} </Text>
          <Text color={theme.amber}>
            {activeTool
              ? `${activeTool.tool}${activeTool.hint ? ` ${activeTool.hint}` : ""}`
              : `${verbRef.current}…`}
          </Text>
          <Text color={tpsTrend === "up" ? theme.green : theme.red}>
            {"  "}
            {tpsLabel}
          </Text>
          <Text color={theme.faint}>
            {" "}· {elapsed}s · esc to interrupt
          </Text>
        </Box>
      )}

      {approval && (
        <Approval
          request={approval.request}
          onDecision={(ok, always) => {
            if (always) loadConfig().yolo = true;
            approval.resolve(ok);
            setApproval(null);
          }}
        />
      )}

      {effortMenu && (
        <Box flexDirection="column" borderStyle="round" borderColor={theme.orange} paddingX={1} marginTop={1}>
          <Text bold color={theme.orange}>
            effort level <Text color={theme.faint}>(↑/↓ · enter · esc)</Text>
          </Text>
          {EFFORT_OPTIONS.map((o, i) => (
            <Text key={o.value}>
              <Text color={i === effortMenuIdx ? theme.orange : theme.faint}>
                {i === effortMenuIdx ? " ❯ " : "   "}
              </Text>
              <Text bold={i === effortMenuIdx} color={i === effortMenuIdx ? theme.ink : theme.dim}>
                {o.value.padEnd(10)}
              </Text>
              <Text color={theme.faint}> {o.blurb}</Text>
              {o.value === cfg.effort ? <Text color={theme.green}> ← current</Text> : null}
            </Text>
          ))}
        </Box>
      )}

      {todos.length > 0 && (
        <Box flexDirection="column" marginTop={1} marginLeft={1}>
          {todos.map((t, i) => (
            <Text key={i}>
              {t.status === "done" ? (
                <Text color={theme.orange}>● </Text>
              ) : t.status === "in_progress" ? (
                <Text color={theme.ink}>◐ </Text>
              ) : (
                <Text color={theme.faint}>○ </Text>
              )}
              <Text
                bold={t.status === "in_progress"}
                color={t.status === "in_progress" ? theme.ink : t.status === "done" ? theme.dim : theme.faint}
                strikethrough={t.status === "done"}
              >
                {t.text}
              </Text>
            </Text>
          ))}
        </Box>
      )}

      {!running && !approval && !effortMenu && (
        <Box flexDirection="column" marginTop={0}>
          <Box borderStyle="round" borderColor={theme.faint} paddingX={1}>
            <Input
              onSubmit={submit}
              onChange={onInputChange}
              history={history}
              suggestionsCount={suggestions.length}
              onSuggestionMove={(d) =>
                setSuggestionIdx((i) => (i + d + suggestions.length) % suggestions.length)
              }
              onSuggestionComplete={() => {
                const s = suggestions[suggestionIdx];
                if (!s) return null;
                const completed = `/${s.name} `;
                onInputChange(completed);
                return completed;
              }}
              onSuggestionAccept={() => {
                const s = suggestions[suggestionIdx];
                if (!s) return null;
                setSuggestions([]);
                return `/${s.name}`;
              }}
            />
          </Box>
          {suggestions.length > 0 && (
            <Box flexDirection="column" marginLeft={2}>
              {suggestions.map((s, i) => (
                <Text key={s.name}>
                  <Text color={i === suggestionIdx ? theme.orange : theme.faint}>
                    {i === suggestionIdx ? "❯ " : "  "}
                  </Text>
                  <Text bold={i === suggestionIdx} color={i === suggestionIdx ? theme.orange : theme.dim}>
                    /{s.name}
                  </Text>
                  <Text color={theme.faint}> — {s.description}</Text>
                </Text>
              ))}
            </Box>
          )}
          <Box marginLeft={1}>
            <Text color={theme.faint}>
              {ctrlCArmed
                ? "press ctrl+c again to quit"
                : `${MODEL.replace("groq/", "")} · effort ${cfg.effort} · ctx ${fmtTok(ctxTokens)} · ${fmtTok(usage.total)} tok · ${formatCost(cost)} · ${cfg.yolo ? "yolo" : "safe"} · diag ${cfg.diagnostics ? "on" : "off"} · /help`}
            </Text>
          </Box>
        </Box>
      )}
    </Box>
  );
}

function Banner(): React.ReactElement {
  return (
    <Box flexDirection="column" marginTop={1}>
      <Text>
        <Text color={theme.orange} bold>
          ✦ glint
        </Text>
        <Text color={theme.dim}> v{VERSION} · Glint Research · a tiny agent that punches above its weight</Text>
      </Text>
      <Text color={theme.faint}>
        {"  "}groq/compound · session {SESSION_ID} · {process.cwd()}
      </Text>
      <Text color={theme.faint}>
        {"  "}/help for commands · ! for shell · traces stay local (opt out: /no-diagnostics)
      </Text>
    </Box>
  );
}

export async function startApp(opts: { yolo: boolean; intro: boolean; resume?: string }): Promise<void> {
  const instance = render(<App opts={opts} />, { exitOnCtrlC: false });
  await instance.waitUntilExit();
  process.stdout.write("\x1b[?1006l\x1b[?1000l");
}
